# =============================================================================
# Chapter 7 figures: Advanced Experimental Designs
#
# Run from the project root:
#   Rscript r_code/figures/chapter_07.R
#
# Figure 7.1 uses maid_mindset.csv. Captions and alt text live here, next to
# the code. figures/chapter_07/figures.yml is generated by save_book_fig(); do
# not edit it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
  library(readr)
  library(dplyr)
  library(tidyr)
  library(car)
  library(emmeans)
})

assert_book_font()

# ---- Data -------------------------------------------------------------------

maid <- read_csv("data/maid_mindset.csv", show_col_types = FALSE)

maid$Age_Group <- factor(
  ifelse(is.na(maid$Age), "NA",
         ifelse(maid$Age < 40, "Under 40", "40+")),
  levels = c("Under 40", "40+", "NA")
)
maid$Condition <- factor(
  ifelse(maid$Cond == 0, "Control", "Informed"),
  levels = c("Control", "Informed")
)

cell_means <- maid %>%
  group_by(Condition, Age_Group) %>%
  summarise(
    mean_syst2 = mean(Syst2, na.rm = TRUE),
    n = sum(!is.na(Syst2)),
    .groups = "drop"
  )

# ---- Figure 7.1: interaction plot for post-intervention blood pressure ------

p71 <- ggplot(
  cell_means,
  aes(
    x = Condition, y = mean_syst2,
    colour = Age_Group, shape = Age_Group, linetype = Age_Group,
    group = Age_Group
  )
) +
  geom_line(
    data = cell_means[cell_means$Age_Group != "NA", ],
    linewidth = 0.8
  ) +
  geom_point(size = 3.2) +
  annotate(
    "text", x = 2.06, y = 116, label = "NA",
    hjust = 0, vjust = -0.6, size = 3.2, colour = BOOK_MUTED
  ) +
  scale_colour_manual(
    values = c(
      "Under 40" = book_palette[["blue"]],
      "40+" = book_palette[["vermillion"]],
      "NA" = BOOK_MUTED
    ),
    name = "Age group"
  ) +
  scale_shape_manual(
    values = c("Under 40" = 16, "40+" = 17, "NA" = 15),
    name = "Age group"
  ) +
  scale_linetype_manual(
    values = c("Under 40" = "solid", "40+" = "dashed", "NA" = "dotted"),
    name = "Age group"
  ) +
  scale_y_continuous(limits = c(112, 134), breaks = seq(115, 135, 5)) +
  labs(
    x = "Condition",
    y = "Systolic blood pressure (mmHg)"
  ) +
  book_theme()

save_book_fig(
  p71,
  chapter = 7, id = "7.1", type = "line",
  slug = "interaction_syst2_condition_age",
  caption = paste(
    "Interaction plot of post-intervention systolic blood pressure by condition",
    "and age group. The Under 40 line slopes down from control to informed,",
    "while the 40+ line slopes up, so the lines are not parallel. The single NA",
    "point marks the maid whose age was missing."
  ),
  alt = paste(
    "Interaction plot with condition on the x-axis and post-intervention",
    "systolic blood pressure on the y-axis. The Under 40 line falls from control",
    "to informed, the 40+ line rises, and a single NA point appears near the",
    "informed position. The 40+ line stays above the Under 40 line."
  ),
  direct_labels = TRUE,
  author_note = paste(
    "The 9 maids with missing Syst2 are excluded from the means. The NA point is",
    "the 1 maid with missing Age (Syst2 = 116), not the 9 missing blood pressure",
    "cases."
  )
)

# =============================================================================
# Chapter 7 values
#
# r_code/chapter_07.r sets sum-to-zero contrasts and uses Type III SS. The same
# setup is reproduced here so figures/chapter_07/values.yml records the exact
# values reported in the chapter, the model call behind each one, and the
# calculation conventions. Regenerate the values with:
#   Rscript r_code/figures/chapter_07.R
# =============================================================================

options(contrasts = c("contr.sum", "contr.poly"))

model_data <- maid
model_data$Cond <- factor(
  model_data$Cond, levels = c(0, 1), labels = c("Control", "Informed")
)
model_data$Age_Group <- factor(
  ifelse(model_data$Age < 40, "Under 40", "40+")
)
model_data$Subject_ID <- factor(seq_len(nrow(model_data)))

plain_df <- function(df) {
  df[] <- lapply(df, function(x) if (is.factor(x)) as.character(x) else x)
  df
}

anova_terms <- function(fit, type = "III") {
  tab <- as.data.frame(car::Anova(fit, type = type))
  tab$term <- rownames(tab)
  rownames(tab) <- NULL
  plain_df(tab)
}

# ---- Models ----------------------------------------------------------------

baseline_fit <- lm(Syst ~ Cond * Age_Group, data = model_data)
post_fit <- lm(Syst2 ~ Cond * Age_Group, data = model_data)
slope_fit <- lm(Syst2 ~ Syst * Cond, data = model_data)
ancova_fit <- lm(Syst2 ~ Syst + Cond, data = model_data)
ancova_em <- plain_df(
  as.data.frame(emmeans::emmeans(ancova_fit, specs = "Cond"))
)

rm_fit <- lm(cbind(BMI, BMI2) ~ Cond, data = model_data)
rm_out <- car::Anova(
  rm_fit,
  idata = data.frame(Time = factor(c("Baseline", "Post_4_Weeks"))),
  idesign = ~Time,
  type = "III"
)
rm_summary <- summary(rm_out, multivariate = FALSE)
rm_terms <- as.data.frame.matrix(rm_summary$univariate)
rm_terms$term <- trimws(rownames(rm_terms))
rownames(rm_terms) <- NULL
rm_terms <- plain_df(rm_terms)

rm_long <- model_data %>%
  pivot_longer(
    cols = c(BMI, BMI2), names_to = "Timepoint", values_to = "BMI_Value"
  ) %>%
  mutate(
    Timepoint = factor(
      Timepoint, levels = c("BMI", "BMI2"),
      labels = c("Baseline", "Post-Intervention")
    )
  )
rm_b <- suppressWarnings(
  aov(BMI_Value ~ Timepoint * Cond + Error(Subject_ID / Timepoint),
      data = rm_long)
)
rm_b_within <- as.data.frame(
  summary(rm_b)[["Error: Subject_ID:Timepoint"]][[1]]
)
rm_b_within$term <- trimws(rownames(rm_b_within))
rownames(rm_b_within) <- NULL
rm_b_within <- plain_df(rm_b_within)

bmi_change <- model_data %>%
  group_by(Cond) %>%
  summarise(
    n_pairs = sum(!is.na(BMI) & !is.na(BMI2)),
    mean_BMI_minus_BMI2 = mean(BMI - BMI2, na.rm = TRUE),
    t = t.test(BMI, BMI2, paired = TRUE)$statistic,
    p = t.test(BMI, BMI2, paired = TRUE)$p.value,
    .groups = "drop"
  )
bmi_change <- plain_df(bmi_change)

figure_cell_means <- plain_df(cell_means)

# ---- Values registry -------------------------------------------------------

values <- list(
  data = list(
    rows = nrow(maid),
    missing_Age = sum(is.na(maid$Age)),
    missing_Syst = sum(is.na(maid$Syst)),
    missing_Syst2 = sum(is.na(maid$Syst2)),
    missing_BMI2 = sum(is.na(maid$BMI2))
  ),
  figure_7_1 = list(
    note = paste(
      "Cell means of post-intervention systolic blood pressure by condition",
      "and age group. The NA row is the one maid missing Age (Syst2 = 116);",
      "the 9 maids missing Syst2 are excluded."
    ),
    cell_means = figure_cell_means
  ),
  table_7_1 = list(
    note = paste(
      "Baseline systolic blood pressure, Type III SS with sum-to-zero",
      "contrasts. This is the table the chapter labels as baseline."
    ),
    model = "lm(Syst ~ Cond * Age_Group, data = model_data)",
    anova = "car::Anova(model, type = 'III')",
    n = nobs(baseline_fit),
    residual_df = df.residual(baseline_fit),
    terms = anova_terms(baseline_fit)
  ),
  table_7_2 = list(
    note = paste(
      "Homogeneity of regression slopes, Type III SS with sum-to-zero",
      "contrasts."
    ),
    model = "lm(Syst2 ~ Syst * Cond, data = model_data)",
    anova = "car::Anova(model, type = 'III')",
    n = nobs(slope_fit),
    residual_df = df.residual(slope_fit),
    terms = anova_terms(slope_fit)
  ),
  table_7_3 = list(
    note = "ANCOVA, Type III SS with sum-to-zero contrasts.",
    model = "lm(Syst2 ~ Syst + Cond, data = model_data)",
    anova = "car::Anova(model, type = 'III')",
    n = nobs(ancova_fit),
    residual_df = df.residual(ancova_fit),
    terms = anova_terms(ancova_fit),
    adjusted_means = ancova_em,
    covariate_mean = mean(model.frame(ancova_fit)$Syst)
  ),
  table_7_4 = list(
    note = paste(
      "Table 7.4 uses Method A, the car::Anova multivariate repeated-measures",
      "output. Method B, the long-format aov, is recorded for comparison."
    ),
    model = "lm(cbind(BMI, BMI2) ~ Cond, data = model_data)",
    anova = paste(
      "car::Anova(model, idata = data.frame(Time = factor(c('Baseline',",
      "'Post_4_Weeks'))), idesign = ~Time, type = 'III')"
    ),
    n = nobs(rm_fit),
    den_df = rm_terms[["den Df"]][1],
    method_A_univariate = rm_terms,
    method_B_within = rm_b_within
  ),
  post_intervention_two_way = list(
    note = paste(
      "Post-intervention model used for the clarifying sentence in Section",
      "7.5. The interaction p = .771 is the value that applies to Figure 7.1.",
      "The model uses the 65 maids with known age; the single NA-age point is",
      "not in the model."
    ),
    model = "lm(Syst2 ~ Cond * Age_Group, data = model_data)",
    anova = "car::Anova(model, type = 'III')",
    n = nobs(post_fit),
    residual_df = df.residual(post_fit),
    terms = anova_terms(post_fit)
  ),
  bmi_change = list(
    note = "Paired before-and-after BMI change by condition (BMI minus BMI2).",
    paired = bmi_change
  )
)

save_book_values(
  chapter = 7,
  values = values,
  conventions = list(
    contrasts = "contr.sum",
    ss_type = "III",
    note = paste(
      "r_code/chapter_07.r sets options(contrasts = c('contr.sum',",
      "'contr.poly')). The chapter tables use Type III SS. Type II or",
      "treatment contrasts give different main-effect and covariate rows,",
      "so these values are the reference for checking the chapter.",
      "The reference script's twoway_fit uses Syst2; Table 7.1's baseline",
      "Syst model is fit here with the same convention."
    ),
    rm = paste(
      "Table 7.4 uses Method A, the car::Anova multivariate output. Method B,",
      "the long-format aov, gives Time F = 16.632; the difference is the SS",
      "calculation, not a data error."
    )
  ),
  source = "r_code/chapter_07.r"
)
